(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.02+t*0.3)*15+Math.cos(y*0.015-t*0.2)*10;
  const w1y = Math.cos(y*0.02-t*0.25)*15+Math.sin(x*0.018+t*0.35)*10;
  const sx = x+w1x, sy = y+w1y;
  const w2x = Math.sin(sy*0.025-t*0.4)*8+Math.cos(sx*0.02+t*0.3)*6;
  const w2y = Math.cos(sx*0.022+t*0.35)*8+Math.sin(sy*0.018-t*0.45)*6;
  const fx = sx+w2x, fy = sy+w2y;
  const src = [
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.08,2.0,1.0],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.1,1.7,0.8],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.06,2.3,1.2],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.12,1.5,0.9],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.07,2.6,1.1],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.09,1.9,0.85],
    [80+Math.sin(t*0.7+3)*70,40+Math.cos(t*0.6+2)*60,0.11,2.1,0.95],
    [400+Math.cos(t*0.45+1)*80,200+Math.sin(t*0.8+4)*50,0.065,2.4,1.05],
    [200+Math.sin(t*0.55+5)*110,30+Math.cos(t*0.75+3)*80,0.095,1.8,0.75],
    [300+Math.cos(t*0.65+2)*95,220+Math.sin(t*0.5+1)*65,0.075,2.2,1.15]
  ];
  let aS=0,iS=0,cS=0;
  for(const[sX,sY,f,sp,w]of src){
    const d=Math.sqrt((fx-sX)**2+(fy-sY)**2);
    aS+=Math.sin(d*f-t*sp)*w;
    iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5)*w;
    cS+=Math.cos(d*f*0.5-t*sp*0.4+3.0)*w*0.5;
  }
  const aN=aS/8.2,iN=iS/8.2,cN=cS/8.2;
  const fbm=(a,b,c,d,e)=>{
    let v=0,amp=1,freq=1,tot=0;
    for(let i=0;i<5;i++){v+=amp*Math.sin(a*freq+b*freq+c*(i*0.7+1)+d*e);tot+=amp;amp*=0.5;freq*=2.1;}
    return v/tot;
  };
  const bg=fbm(fx*0.03,fy*0.025,t*0.8,1.0,0.5)+fbm(fx*0.04-fy*0.02,fy*0.035,t*1.1,1.5,0.7)*0.6;
  const dist=Math.sqrt((fx-cx)**2+(fy-cy)**2),ang=Math.atan2(fy-cy,fx-cx);
  const sp1=Math.sin(dist*0.05-ang*3-t*1.5),sp2=Math.sin(dist*0.04+ang*4-t*1.2);
  const sp3=Math.sin(dist*0.07-ang*2+t*0.9),sp4=Math.cos(dist*0.035+ang*5-t*1.8);
  const spiral=(sp1+sp2)*0.25+(sp3+sp4)*0.15;
  const cell=Math.tanh((Math.sin(fx*0.15)*Math.sin(fy*0.15)+Math.sin((fx+fy)*0.1+t)*0.5+Math.sin((fx-fy)*0.12-t*1.3)*0.3)*1.5)*0.3;
  const cross=Math.sin(fx*0.08)*Math.sin(fy*0.08)*0.4;
  const react=Math.tanh((aN-iN*0.65+bg*0.25+spiral+cN*0.3)*2.0);
  const detail=Math.sin(fx*0.3+t*2)*Math.sin(fy*0.3-t*1.7)*0.08;
  const blend=react*0.6+cell*0.2+cross*0.1+detail,v=blend*0.5+0.5;
  const pulse=0.85+Math.sin(t*0.5)*0.1+Math.sin(t*0.8+2)*0.05;
  const pal=[
    [6,12,52],[12,48,95],[18,85,125],[28,135,140],
    [80,175,155],[180,195,90],[215,165,60],[225,120,55],
    [195,75,65],[155,45,75],[90,25,65],[35,15,55],[6,12,52]
  ];
  const idx=v*(pal.length-1),i=Math.min(idx|0,pal.length-2),f=idx-i;
  const sm=f*f*(3-2*f);
  const lum=pulse*(0.82+Math.sin(react*Math.PI)*0.18);
  const edge=Math.abs(react)>0.65?1.18:Math.abs(react)>0.4?1.05:0.92;
  const glow=Math.max(0,1-Math.abs(react)*1.2)*0.15;
  return[
    Math.min(255,((pal[i][0]+(pal[i+1][0]-pal[i][0])*sm)*lum*edge+glow*40)|0),
    Math.min(255,((pal[i][1]+(pal[i+1][1]-pal[i][1])*sm)*lum*edge+glow*60)|0),
    Math.min(255,((pal[i][2]+(pal[i+1][2]-pal[i][2])*sm)*lum*edge+glow*80)|0)
  ];
}
